'use strict';

const APP_VERSION = 3;
const DB_NAME = 'electrical_store_manager_prod';
const DB_STORE = 'app';
const DB_KEY = 'state';
const qs = (s, root=document) => root.querySelector(s);
const qsa = (s, root=document) => [...root.querySelectorAll(s)];
const todayISO = () => new Date().toISOString().slice(0,10);
const nowISO = () => new Date().toISOString();
const uid = (prefix='id') => `${prefix}_${(crypto.randomUUID ? crypto.randomUUID() : Date.now()+'_'+Math.random().toString(36).slice(2))}`;
const n = v => Number(v || 0);
const round2 = v => Math.round((Number(v) + Number.EPSILON) * 100) / 100;
const clamp = (v,min,max) => Math.min(max,Math.max(min,v));
const esc = (v='') => String(v).replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':'&quot;'}[c]));
const dateFmt = v => { if(!v) return '—'; const d=new Date(v.length===10?v+'T00:00:00':v); return isNaN(d)?v:d.toLocaleDateString('en-PK',{day:'2-digit',month:'short',year:'numeric'}); };
const dateTimeFmt = v => { if(!v) return '—'; const d=new Date(v); return isNaN(d)?v:d.toLocaleString('en-PK',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}); };
const csvCell = v => `"${String(v ?? '').replaceAll('"','""')}"`;

let state;
let currentPage = 'dashboard';
let currentTabs = { cashbook:'cash', reports:'profit' };
let posCart = [];
let purchaseCart = [];
let dbPromise;
let saveTimer;

const DEFAULT_STATE = () => ({
  schemaVersion: APP_VERSION,
  settings: {
    shopName: 'Electrical Store', address:'', phone:'', whatsapp:'', ownerName:'',
    currency:'PKR', invoicePrefix:'INV', purchasePrefix:'PUR', lowStockDefault:5,
    adminPin:'', pinEnabled:false, lastBackupAt:null, createdAt:nowISO()
  },
  counters: { sale:1, purchase:1, customerPayment:1, supplierPayment:1, cash:1 },
  products: [], customers: [], suppliers: [], sales: [], purchases: [], expenses: [],
  cashEntries: [], customerLedger: [], supplierLedger: [], audit: []
});

function migrate(raw){
  const base = DEFAULT_STATE();
  if(!raw || typeof raw !== 'object') return base;
  const merged = {...base, ...raw};
  merged.settings = {...base.settings, ...(raw.settings||{})};
  merged.counters = {...base.counters, ...(raw.counters||{})};
  for(const k of ['products','customers','suppliers','sales','purchases','expenses','cashEntries','customerLedger','supplierLedger','audit']) if(!Array.isArray(merged[k])) merged[k]=[];
  merged.schemaVersion=APP_VERSION;
  return merged;
}

function openDB(){
  if(dbPromise) return dbPromise;
  dbPromise = new Promise((resolve,reject)=>{
    const req = indexedDB.open(DB_NAME,1);
    req.onupgradeneeded = () => { const db=req.result; if(!db.objectStoreNames.contains(DB_STORE)) db.createObjectStore(DB_STORE); };
    req.onsuccess=()=>resolve(req.result); req.onerror=()=>reject(req.error);
  });
  return dbPromise;
}
async function loadState(){
  try{
    const db=await openDB();
    const value=await new Promise((resolve,reject)=>{ const tx=db.transaction(DB_STORE,'readonly'); const req=tx.objectStore(DB_STORE).get(DB_KEY); req.onsuccess=()=>resolve(req.result); req.onerror=()=>reject(req.error); });
    return migrate(value);
  }catch(e){
    console.warn('IndexedDB unavailable, using localStorage fallback',e);
    try{return migrate(JSON.parse(localStorage.getItem(DB_NAME)||'null'));}catch{return DEFAULT_STATE();}
  }
}
async function persist(){
  try{
    const db=await openDB();
    await new Promise((resolve,reject)=>{ const tx=db.transaction(DB_STORE,'readwrite'); tx.objectStore(DB_STORE).put(state,DB_KEY); tx.oncomplete=resolve; tx.onerror=()=>reject(tx.error); });
  }catch(e){ localStorage.setItem(DB_NAME,JSON.stringify(state)); }
}
function queueSave(){ clearTimeout(saveTimer); saveTimer=setTimeout(()=>persist(),80); }
function audit(action,details=''){ state.audit.unshift({id:uid('aud'),at:nowISO(),action,details}); state.audit=state.audit.slice(0,500); queueSave(); }

function money(v){ return new Intl.NumberFormat('en-PK',{style:'currency',currency:state?.settings?.currency||'PKR',maximumFractionDigits:0}).format(n(v)); }
function saleNo(){ const x=state.counters.sale++; return `${state.settings.invoicePrefix}-${String(x).padStart(6,'0')}`; }
function purchaseNo(){ const x=state.counters.purchase++; return `${state.settings.purchasePrefix}-${String(x).padStart(6,'0')}`; }
function productById(id){return state.products.find(x=>x.id===id)}
function customerById(id){return state.customers.find(x=>x.id===id)}
function supplierById(id){return state.suppliers.find(x=>x.id===id)}
function customerBalance(id){return round2(state.customerLedger.filter(x=>x.customerId===id).reduce((s,x)=>s+n(x.amount),0));}
function supplierBalance(id){return round2(state.supplierLedger.filter(x=>x.supplierId===id).reduce((s,x)=>s+n(x.amount),0));}
function cashBalance(method){return round2(state.cashEntries.filter(x=>!method||x.method===method).reduce((s,x)=>s+(x.direction==='in'?n(x.amount):-n(x.amount)),0));}
function activeSales(){return state.sales.filter(x=>x.status!=='reversed')}
function activePurchases(){return state.purchases.filter(x=>x.status!=='reversed')}
function inRange(date,from,to){ const d=(date||'').slice(0,10); return (!from||d>=from)&&(!to||d<=to); }
function monthRange(){const d=new Date();const from=new Date(d.getFullYear(),d.getMonth(),1);return {from:from.toISOString().slice(0,10),to:todayISO()};}

const NAV = [
  ['dashboard','▦','Dashboard'],['pos','🛒','Point of Sale'],['products','📦','Products & Prices'],['purchases','🚚','Purchases'],['sales','🧾','Sales History'],
  ['customers','👥','Customers / Udhaar'],['suppliers','🏭','Suppliers'],['cashbook','💵','Expenses & Cashbook'],['reports','📊','Reports'],['settings','⚙️','Settings & Backup']
];
const PAGE_META = {
  dashboard:['Dashboard','Overview of sales, profit, stock and cash'],pos:['Point of Sale','Create a sale and print a receipt'],products:['Products & Prices','Inventory, pricing and quick price lookup'],
  purchases:['Purchases','Receive stock and track supplier payables'],sales:['Sales History','Invoices, returns and receipts'],customers:['Customers / Udhaar','Track customer balances and collections'],
  suppliers:['Suppliers','Track supplier balances and payments'],cashbook:['Expenses & Cashbook','All money coming in and going out'],reports:['Reports','Profit, inventory and business performance'],settings:['Settings & Backup','Shop profile, security and data backup']
};

function renderNav(){
  qs('#nav').innerHTML=NAV.map(([id,icon,label])=>`<button class="nav-btn ${currentPage===id?'active':''}" data-nav="${id}"><span class="nav-icon">${icon}</span><span>${label}</span></button>`).join('');
}
function setPage(page){ currentPage=page; renderNav(); const meta=PAGE_META[page]||['Store','']; qs('#pageTitle').textContent=meta[0]; qs('#pageSubtitle').textContent=meta[1]; qs('.sidebar')?.classList.remove('open'); renderPage(); window.scrollTo({top:0,behavior:'smooth'}); }
function updateBrand(){ qs('#brandTitle').textContent=state.settings.shopName||'Electrical Store'; const last=state.settings.lastBackupAt?new Date(state.settings.lastBackupAt):null; const days=last?Math.floor((Date.now()-last.getTime())/86400000):999; const b=qs('#backupBadge'); b.textContent=days<=7?`Backup ${days===0?'today':days+'d ago'}`:'Backup recommended'; b.style.background=days<=7?'#0f2c26':'#2a1f0c'; b.style.color=days<=7?'#99f6e4':'#fde68a'; }
function toast(msg,type='good'){ const el=document.createElement('div'); el.className=`toast ${type}`; el.textContent=msg; qs('#toastRoot').appendChild(el); setTimeout(()=>el.remove(),3600); }
function confirmDialog(title,message,onConfirm,danger=false){ modal(title,`<div class="stack"><div>${message}</div><div class="alert ${danger?'alert-danger':'alert-warn'}">This action cannot be undone automatically.</div></div>`, `<button class="btn btn-outline" data-action="close-modal">Cancel</button><button id="confirmModalBtn" class="btn ${danger?'btn-danger':'btn-primary'}">Confirm</button>`); setTimeout(()=>qs('#confirmModalBtn')?.addEventListener('click',()=>{closeModal();onConfirm();}),0); }
function modal(title,body,footer='',large=false){ qs('#modalRoot').innerHTML=`<div class="modal-backdrop" data-action="close-modal-bg"><div class="modal ${large?'modal-lg':''}"><div class="modal-head"><h3>${title}</h3><button class="modal-close" data-action="close-modal">✕</button></div><div class="modal-body">${body}</div>${footer?`<div class="modal-foot">${footer}</div>`:''}</div></div>`; }
function closeModal(){qs('#modalRoot').innerHTML=''}
function badge(text,type='gray'){return `<span class="badge badge-${type}">${esc(text)}</span>`}
function empty(icon,title,desc=''){return `<div class="empty"><div class="empty-icon">${icon}</div><div class="strong">${esc(title)}</div>${desc?`<div class="muted" style="margin-top:5px">${esc(desc)}</div>`:''}</div>`}

function renderPage(){
  updateBrand();
  const fn={dashboard:renderDashboard,pos:renderPOS,products:renderProducts,purchases:renderPurchases,sales:renderSales,customers:renderCustomers,suppliers:renderSuppliers,cashbook:renderCashbook,reports:renderReports,settings:renderSettings}[currentPage]||renderDashboard;
  fn();
}

function dashboardStats(){
  const {from,to}=monthRange(); const sales=activeSales().filter(s=>inRange(s.date,from,to)); const revenue=round2(sales.reduce((a,s)=>a+n(s.total),0)); const cogs=round2(sales.flatMap(s=>s.items||[]).reduce((a,i)=>a+n(i.qty)*n(i.costAtSale),0)); const expenses=round2(state.expenses.filter(e=>inRange(e.date,from,to)&&e.status!=='reversed').reduce((a,e)=>a+n(e.amount),0));
  return {revenue,cogs,gross:revenue-cogs,expenses,net:revenue-cogs-expenses};
}
function renderDashboard(){
  const st=dashboardStats(); const low=state.products.filter(p=>p.active!==false&&n(p.stock)<=n(p.minStock??state.settings.lowStockDefault)).sort((a,b)=>n(a.stock)-n(b.stock));
  const receivables=round2(state.customers.reduce((s,c)=>s+Math.max(0,customerBalance(c.id)),0)); const payables=round2(state.suppliers.reduce((s,c)=>s+Math.max(0,supplierBalance(c.id)),0)); const stockValue=round2(state.products.reduce((s,p)=>s+n(p.stock)*n(p.costPrice),0));
  const recent=activeSales().slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,8);
  qs('#main').innerHTML=`
  ${(!state.settings.lastBackupAt||Date.now()-new Date(state.settings.lastBackupAt).getTime()>7*86400000)?`<div class="alert alert-warn no-print" style="margin-bottom:16px">⚠️ Your shop data is stored on this device. Export a backup regularly. <button class="link-btn" data-action="export-backup">Download backup now</button></div>`:''}
  <div class="grid grid-5">
    <div class="card metric"><div class="metric-label">THIS MONTH SALES</div><div class="metric-value">${money(st.revenue)}</div><div class="metric-foot">Gross revenue</div></div>
    <div class="card metric good"><div class="metric-label">NET PROFIT</div><div class="metric-value">${money(st.net)}</div><div class="metric-foot">After COGS & expenses</div></div>
    <div class="card metric"><div class="metric-label">CASH / FUNDS</div><div class="metric-value">${money(cashBalance())}</div><div class="metric-foot">Recorded inflows less outflows</div></div>
    <div class="card metric warn"><div class="metric-label">CUSTOMER UDHAAR</div><div class="metric-value">${money(receivables)}</div><div class="metric-foot">Outstanding receivables</div></div>
    <div class="card metric"><div class="metric-label">STOCK VALUE</div><div class="metric-value">${money(stockValue)}</div><div class="metric-foot">At current cost</div></div>
  </div>
  <div class="grid grid-3 section">
    <div class="card" style="grid-column:span 2"><div class="section-head"><div><div class="card-title">Quick price finder</div><div class="card-subtitle">Search by product name, SKU or barcode</div></div></div><div class="quick-lookup"><input id="dashPriceSearch" class="input" placeholder="e.g. 10A switch, LED bulb, SKU…" autofocus><button class="btn btn-primary" data-action="dashboard-price-search">Find price</button></div><div id="dashLookupResult"></div></div>
    <div class="card"><div class="card-title">Business position</div><div class="stack" style="margin-top:14px"><div class="total-line"><span>Gross profit</span><strong>${money(st.gross)}</strong></div><div class="total-line"><span>Expenses</span><strong>${money(st.expenses)}</strong></div><div class="total-line"><span>Supplier payable</span><strong>${money(payables)}</strong></div><div class="total-line"><span>Low-stock items</span><strong>${low.length}</strong></div></div></div>
  </div>
  <div class="grid grid-2 section">
    <div class="card"><div class="section-head"><div><div class="card-title">Low stock</div><div class="card-subtitle">Items that need attention</div></div><div class="section-actions"><button class="btn btn-outline btn-small" data-nav="products">View inventory</button></div></div>${low.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Product</th><th>Stock</th><th>Min</th><th>Price</th></tr></thead><tbody>${low.slice(0,8).map(p=>`<tr><td><strong>${esc(p.name)}</strong><div class="muted">${esc(p.sku||'')}</div></td><td>${badge(p.stock<=0?'Out':String(p.stock),p.stock<=0?'danger':'warn')}</td><td>${n(p.minStock)}</td><td class="money">${money(p.salePrice)}</td></tr>`).join('')}</tbody></table></div>`:empty('✅','Stock levels look fine','No product is below its minimum level.')}</div>
    <div class="card"><div class="section-head"><div><div class="card-title">Recent sales</div><div class="card-subtitle">Latest completed invoices</div></div><div class="section-actions"><button class="btn btn-outline btn-small" data-nav="sales">All sales</button></div></div>${recent.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Invoice</th><th>Date</th><th>Customer</th><th class="text-right">Total</th></tr></thead><tbody>${recent.map(s=>`<tr><td><button class="link-btn" data-action="view-sale" data-id="${s.id}">${esc(s.number)}</button></td><td>${dateFmt(s.date)}</td><td>${esc(customerById(s.customerId)?.name||'Walk-in')}</td><td class="money text-right">${money(s.total)}</td></tr>`).join('')}</tbody></table></div>`:empty('🧾','No sales yet','Create your first sale from Point of Sale.')}</div>
  </div>`;
}

function productMatches(query, limit=30){
  const q=(query||'').trim().toLowerCase(); let items=state.products.filter(p=>p.active!==false); if(q) items=items.filter(p=>[p.name,p.sku,p.barcode,p.category,p.brand].some(v=>String(v||'').toLowerCase().includes(q))); return items.slice(0,limit);
}
function renderPOS(){
  const products=productMatches('');
  qs('#main').innerHTML=`<div class="pos-layout">
  <div class="card"><div class="section-head"><div><div class="card-title">Add products</div><div class="card-subtitle">Search product name, SKU or scan/type barcode</div></div></div><input id="posSearch" class="input" placeholder="Start typing or scan barcode…" autocomplete="off"><div id="posResults" class="product-search-results">${posProductTiles(products)}</div></div>
  <div class="card cart"><div class="section-head"><div><div class="card-title">Current sale</div><div class="card-subtitle" id="cartCount">${posCart.length} line item(s)</div></div><div class="section-actions"><button class="btn btn-outline btn-small" data-action="clear-pos-cart">Clear</button></div></div><div id="posCartItems" class="cart-items">${posCartHTML()}</div><div id="posCheckout">${posCheckoutHTML()}</div></div></div>`;
}
function posProductTiles(products){ return products.length?products.map(p=>`<button class="product-tile" data-action="add-pos-product" data-id="${p.id}" ${n(p.stock)<=0?'disabled':''}><div class="product-tile-name">${esc(p.name)}</div><div class="product-tile-meta">${esc(p.sku||'No SKU')} · Stock ${n(p.stock)} ${esc(p.unit||'pcs')}</div><div class="product-tile-price">${money(p.salePrice)}</div></button>`).join(''):empty('🔎','No matching products','Add products in Products & Prices.'); }
function posCartHTML(){ if(!posCart.length)return empty('🛒','Cart is empty','Click a product to add it to the sale.'); return posCart.map((x,i)=>{const p=productById(x.productId);return `<div class="cart-row"><div><div class="cart-name">${esc(p?.name||'Deleted product')}</div><div class="cart-meta">Stock ${n(p?.stock)} · ${esc(p?.unit||'pcs')}</div></div><input class="qty-input" type="number" min="0.01" step="0.01" value="${x.qty}" data-cart-qty="${i}"><input class="price-input" type="number" min="0" step="0.01" value="${x.price}" data-cart-price="${i}"><button class="remove-btn" data-action="remove-pos-line" data-index="${i}">×</button></div>`}).join(''); }
function posTotals(){ const subtotal=round2(posCart.reduce((s,x)=>s+n(x.qty)*n(x.price),0)); const discount=n(qs('#posDiscount')?.value||0); const total=Math.max(0,round2(subtotal-discount)); const paid=n(qs('#posPaid')?.value||total); return {subtotal,discount,total,paid:Math.min(paid,total),credit:Math.max(0,total-paid)}; }
function posCheckoutHTML(){ const subtotal=round2(posCart.reduce((s,x)=>s+n(x.qty)*n(x.price),0)); const customerOptions=state.customers.filter(c=>c.active!==false).sort((a,b)=>a.name.localeCompare(b.name)).map(c=>`<option value="${c.id}">${esc(c.name)} (${money(customerBalance(c.id))})</option>`).join(''); return `<div class="totals"><div class="field span-12" style="margin-bottom:10px"><label>Customer</label><select id="posCustomer" class="select"><option value="">Walk-in / Cash customer</option>${customerOptions}</select></div><div class="grid grid-2"><div class="field span-12"><label>Discount</label><input id="posDiscount" class="input" type="number" min="0" step="1" value="0"></div><div class="field span-12"><label>Payment method</label><select id="posMethod" class="select"><option>Cash</option><option>Bank</option><option>Card</option><option>EasyPaisa</option><option>JazzCash</option><option>Other</option></select></div></div><div class="field span-12" style="margin-top:10px"><label>Amount paid now</label><input id="posPaid" class="input" type="number" min="0" step="1" value="${subtotal}"></div><div id="posTotalsBox"><div class="total-line"><span>Subtotal</span><span class="money">${money(subtotal)}</span></div><div class="total-line grand"><span>Total</span><span class="money">${money(subtotal)}</span></div></div><button class="btn btn-primary" style="width:100%;margin-top:12px;padding:13px" data-action="complete-sale" ${!posCart.length?'disabled':''}>Complete sale & save</button></div>`; }
function updatePOSCartUI(){ if(currentPage!=='pos')return; const items=qs('#posCartItems'), checkout=qs('#posCheckout'), count=qs('#cartCount'); if(items)items.innerHTML=posCartHTML(); if(checkout)checkout.innerHTML=posCheckoutHTML(); if(count)count.textContent=`${posCart.length} line item(s)`; }
function updatePOSTotals(){ if(currentPage!=='pos')return; const t=posTotals(); const box=qs('#posTotalsBox'); if(box)box.innerHTML=`<div class="total-line"><span>Subtotal</span><span class="money">${money(t.subtotal)}</span></div><div class="total-line"><span>Discount</span><span class="money">-${money(t.discount)}</span></div><div class="total-line grand"><span>Total</span><span class="money">${money(t.total)}</span></div>${t.credit>0?`<div class="total-line credit"><span>Customer credit / udhaar</span><span>${money(t.credit)}</span></div>`:''}`; }

function renderProducts(){
  const rows=state.products.slice().sort((a,b)=>a.name.localeCompare(b.name));
  qs('#main').innerHTML=`<div class="card"><div class="section-head"><div><div class="card-title">Product catalogue</div><div class="card-subtitle">Keep buying price, selling price, stock, SKU and barcode in one place</div></div><div class="section-actions"><button class="btn btn-outline" data-action="import-products">Import CSV</button><button class="btn btn-outline" data-action="export-products">Export CSV</button><button class="btn btn-primary" data-action="add-product">＋ Add product</button></div></div><div class="searchbar"><input id="productSearch" class="input" placeholder="Search name, SKU, category or barcode"><select id="productStockFilter" class="select" style="max-width:190px"><option value="all">All stock</option><option value="low">Low stock</option><option value="out">Out of stock</option></select></div><div id="productsTable" style="margin-top:14px">${productsTable(rows)}</div></div>`;
}
function productsTable(rows){ if(!rows.length)return empty('📦','No products yet','Add products manually or import them from CSV.'); return `<div class="table-wrap"><table class="table"><thead><tr><th>Product</th><th>Category</th><th>Cost</th><th>Sale price</th><th>Stock</th><th>Stock value</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${esc(p.name)}</strong><div class="muted">${esc(p.sku||'No SKU')}${p.barcode?' · '+esc(p.barcode):''}</div></td><td>${esc(p.category||'—')}<div class="muted">${esc(p.brand||'')}</div></td><td class="money">${money(p.costPrice)}</td><td class="money"><strong>${money(p.salePrice)}</strong></td><td>${n(p.stock)<=0?badge('Out','danger'):n(p.stock)<=n(p.minStock)?badge(`${p.stock} ${p.unit||''}`,'warn'):badge(`${p.stock} ${p.unit||''}`,'good')}</td><td class="money">${money(n(p.stock)*n(p.costPrice))}</td><td class="nowrap"><button class="btn btn-outline btn-small" data-action="edit-product" data-id="${p.id}">Edit</button> <button class="btn btn-outline btn-small" data-action="adjust-stock" data-id="${p.id}">Adjust</button></td></tr>`).join('')}</tbody></table></div>`; }
function productForm(p={}){ return `<form id="productForm"><div class="form-grid"><div class="field span-6"><label>Product name *</label><input class="input" name="name" required value="${esc(p.name||'')}"></div><div class="field span-3"><label>SKU</label><input class="input" name="sku" value="${esc(p.sku||'')}"></div><div class="field span-3"><label>Barcode</label><input class="input" name="barcode" value="${esc(p.barcode||'')}"></div><div class="field span-4"><label>Category</label><input class="input" name="category" value="${esc(p.category||'')}"></div><div class="field span-4"><label>Brand</label><input class="input" name="brand" value="${esc(p.brand||'')}"></div><div class="field span-4"><label>Unit</label><select class="select" name="unit">${['pcs','box','meter','roll','pack','pair','kg','other'].map(u=>`<option ${p.unit===u?'selected':''}>${u}</option>`).join('')}</select></div><div class="field span-3"><label>Buying / cost price *</label><input class="input" name="costPrice" type="number" min="0" step="0.01" required value="${n(p.costPrice)}"></div><div class="field span-3"><label>Selling price *</label><input class="input" name="salePrice" type="number" min="0" step="0.01" required value="${n(p.salePrice)}"></div><div class="field span-3"><label>Current stock</label><input class="input" name="stock" type="number" step="0.01" value="${n(p.stock)}"></div><div class="field span-3"><label>Minimum stock</label><input class="input" name="minStock" type="number" min="0" step="0.01" value="${p.minStock??state.settings.lowStockDefault}"></div><div class="field span-12"><label>Notes</label><textarea class="textarea" name="notes">${esc(p.notes||'')}</textarea></div></div><input type="hidden" name="id" value="${esc(p.id||'')}"></form>`; }

function renderPurchases(){
  const products=productMatches('');
  qs('#main').innerHTML=`<div class="grid grid-2"><div class="card"><div class="section-head"><div><div class="card-title">Receive stock</div><div class="card-subtitle">Create a purchase from a supplier</div></div></div><div class="form-grid"><div class="field span-6"><label>Supplier</label><select id="purchaseSupplier" class="select"><option value="">No supplier / cash purchase</option>${state.suppliers.filter(s=>s.active!==false).map(s=>`<option value="${s.id}">${esc(s.name)} (${money(supplierBalance(s.id))})</option>`).join('')}</select></div><div class="field span-3"><label>Date</label><input id="purchaseDate" class="input" type="date" value="${todayISO()}"></div><div class="field span-3"><label>Supplier invoice</label><input id="supplierInvoice" class="input" placeholder="Optional"></div><div class="field span-12"><label>Search product</label><input id="purchaseSearch" class="input" placeholder="Name / SKU / barcode"></div></div><div id="purchaseResults" class="product-search-results" style="max-height:280px">${purchaseProductTiles(products)}</div></div><div class="card"><div class="section-head"><div><div class="card-title">Purchase cart</div><div class="card-subtitle">Quantity and buying price can be edited</div></div><div class="section-actions"><button class="btn btn-outline btn-small" data-action="clear-purchase-cart">Clear</button></div></div><div id="purchaseCart">${purchaseCartHTML()}</div><div id="purchaseCheckout">${purchaseCheckoutHTML()}</div></div></div><div class="card section"><div class="section-head"><div><div class="card-title">Recent purchases</div><div class="card-subtitle">Stock received from suppliers</div></div></div>${purchasesTable(activePurchases().slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)).slice(0,20))}</div>`;
}
function purchaseProductTiles(products){return products.length?products.map(p=>`<button class="product-tile" data-action="add-purchase-product" data-id="${p.id}"><div class="product-tile-name">${esc(p.name)}</div><div class="product-tile-meta">${esc(p.sku||'No SKU')} · Stock ${n(p.stock)}</div><div class="product-tile-price">Cost ${money(p.costPrice)}</div></button>`).join(''):empty('🔎','No products found');}
function purchaseCartHTML(){if(!purchaseCart.length)return empty('🚚','Purchase cart is empty','Add products that arrived from the supplier.'); return `<div class="table-wrap"><table class="table"><thead><tr><th>Product</th><th>Qty</th><th>Cost each</th><th>Total</th><th></th></tr></thead><tbody>${purchaseCart.map((x,i)=>{const p=productById(x.productId);return `<tr><td><strong>${esc(p?.name||'Product')}</strong></td><td><input class="qty-input" data-purchase-qty="${i}" type="number" min="0.01" step="0.01" value="${x.qty}"></td><td><input class="price-input" data-purchase-cost="${i}" type="number" min="0" step="0.01" value="${x.cost}"></td><td class="money">${money(n(x.qty)*n(x.cost))}</td><td><button class="remove-btn" data-action="remove-purchase-line" data-index="${i}">×</button></td></tr>`}).join('')}</tbody></table></div>`;}
function purchaseCheckoutHTML(){const total=round2(purchaseCart.reduce((s,x)=>s+n(x.qty)*n(x.cost),0));return `<div class="totals"><div class="grid grid-2"><div class="field span-12"><label>Payment method</label><select id="purchaseMethod" class="select"><option>Cash</option><option>Bank</option><option>Card</option><option>EasyPaisa</option><option>JazzCash</option><option>Other</option></select></div><div class="field span-12"><label>Amount paid now</label><input id="purchasePaid" class="input" type="number" min="0" step="1" value="${total}"></div></div><div class="total-line grand"><span>Purchase total</span><span>${money(total)}</span></div><button class="btn btn-primary" style="width:100%;margin-top:12px" data-action="complete-purchase" ${!purchaseCart.length?'disabled':''}>Save purchase & update stock</button></div>`;}
function purchasesTable(rows){if(!rows.length)return empty('🚚','No purchases yet');return `<div class="table-wrap"><table class="table"><thead><tr><th>Purchase</th><th>Date</th><th>Supplier</th><th>Items</th><th>Paid</th><th class="text-right">Total</th></tr></thead><tbody>${rows.map(p=>`<tr><td><strong>${esc(p.number)}</strong><div class="muted">${esc(p.supplierInvoice||'')}</div></td><td>${dateFmt(p.date)}</td><td>${esc(supplierById(p.supplierId)?.name||'Cash purchase')}</td><td>${p.items?.length||0}</td><td>${money(p.paidAmount)}</td><td class="money text-right">${money(p.total)}</td></tr>`).join('')}</tbody></table></div>`;}
function updatePurchaseUI(){ if(currentPage!=='purchases')return; if(qs('#purchaseCart'))qs('#purchaseCart').innerHTML=purchaseCartHTML(); if(qs('#purchaseCheckout'))qs('#purchaseCheckout').innerHTML=purchaseCheckoutHTML(); }

function renderSales(){
  const rows=state.sales.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  qs('#main').innerHTML=`<div class="card"><div class="section-head"><div><div class="card-title">Sales invoices</div><div class="card-subtitle">Search invoices and handle full returns</div></div><div class="section-actions"><button class="btn btn-primary" data-nav="pos">＋ New sale</button></div></div><div class="searchbar"><input id="salesSearch" class="input" placeholder="Invoice, customer or product"><input id="salesFrom" class="input" type="date" style="max-width:170px"><input id="salesTo" class="input" type="date" style="max-width:170px"></div><div id="salesTable" style="margin-top:14px">${salesTable(rows)}</div></div>`;
}
function salesTable(rows){if(!rows.length)return empty('🧾','No sales found');return `<div class="table-wrap"><table class="table"><thead><tr><th>Invoice</th><th>Date</th><th>Customer</th><th>Payment</th><th>Paid</th><th>Credit</th><th class="text-right">Total</th><th></th></tr></thead><tbody>${rows.map(s=>`<tr style="${s.status==='reversed'?'opacity:.55':''}"><td><button class="link-btn" data-action="view-sale" data-id="${s.id}">${esc(s.number)}</button><div>${s.status==='reversed'?badge('Returned','danger'):badge('Completed','good')}</div></td><td>${dateFmt(s.date)}</td><td>${esc(customerById(s.customerId)?.name||'Walk-in')}</td><td>${esc(s.paymentMethod||'')}</td><td class="money">${money(s.paidAmount)}</td><td class="money">${money(s.creditAmount)}</td><td class="money text-right">${money(s.total)}</td><td class="nowrap"><button class="btn btn-outline btn-small" data-action="print-sale" data-id="${s.id}">Print</button>${s.status!=='reversed'?` <button class="btn btn-outline btn-small" data-action="reverse-sale" data-id="${s.id}">Return</button>`:''}</td></tr>`).join('')}</tbody></table></div>`;}

function renderCustomers(){
  const rows=state.customers.slice().sort((a,b)=>a.name.localeCompare(b.name));
  const total=round2(rows.reduce((s,c)=>s+Math.max(0,customerBalance(c.id)),0));
  qs('#main').innerHTML=`<div class="grid grid-3"><div class="card metric warn"><div class="metric-label">TOTAL CUSTOMER UDHAAR</div><div class="metric-value">${money(total)}</div><div class="metric-foot">Amount customers owe the shop</div></div><div class="card metric"><div class="metric-label">CUSTOMERS</div><div class="metric-value">${rows.length}</div><div class="metric-foot">Saved customer accounts</div></div><div class="card"><div class="card-title">Quick collection</div><div class="card-subtitle">Record payment from a customer</div><button class="btn btn-primary" style="margin-top:12px" data-action="customer-payment">＋ Receive udhaar payment</button></div></div><div class="card section"><div class="section-head"><div><div class="card-title">Customer accounts</div><div class="card-subtitle">Click a customer to view complete ledger</div></div><div class="section-actions"><button class="btn btn-primary" data-action="add-customer">＋ Add customer</button></div></div><div class="searchbar"><input id="customerSearch" class="input" placeholder="Search customer or phone"></div><div id="customersTable" style="margin-top:14px">${customersTable(rows)}</div></div>`;
}
function customersTable(rows){if(!rows.length)return empty('👥','No customers yet','Add customers when you sell on credit.');return `<div class="table-wrap"><table class="table"><thead><tr><th>Customer</th><th>Phone</th><th>Address</th><th>Balance</th><th></th></tr></thead><tbody>${rows.map(c=>{const b=customerBalance(c.id);return `<tr><td><button class="link-btn" data-action="view-customer" data-id="${c.id}">${esc(c.name)}</button></td><td>${esc(c.phone||'—')}</td><td>${esc(c.address||'—')}</td><td class="money ${b>0?'text-warn':b<0?'text-good':''}">${money(b)}</td><td class="nowrap"><button class="btn btn-outline btn-small" data-action="customer-payment" data-id="${c.id}">Payment</button> <button class="btn btn-outline btn-small" data-action="edit-customer" data-id="${c.id}">Edit</button></td></tr>`}).join('')}</tbody></table></div>`;}
function customerForm(c={}){return `<form id="customerForm"><div class="form-grid"><div class="field span-6"><label>Name *</label><input class="input" name="name" required value="${esc(c.name||'')}"></div><div class="field span-6"><label>Phone</label><input class="input" name="phone" value="${esc(c.phone||'')}"></div><div class="field span-8"><label>Address</label><input class="input" name="address" value="${esc(c.address||'')}"></div><div class="field span-4"><label>Opening udhaar</label><input class="input" name="openingBalance" type="number" step="0.01" value="${c.id?0:n(c.openingBalance)}" ${c.id?'disabled':''}></div><div class="field span-12"><label>Notes</label><textarea class="textarea" name="notes">${esc(c.notes||'')}</textarea></div></div><input type="hidden" name="id" value="${esc(c.id||'')}"></form>`;}

function renderSuppliers(){
  const rows=state.suppliers.slice().sort((a,b)=>a.name.localeCompare(b.name)); const total=round2(rows.reduce((s,c)=>s+Math.max(0,supplierBalance(c.id)),0));
  qs('#main').innerHTML=`<div class="grid grid-3"><div class="card metric danger"><div class="metric-label">SUPPLIER PAYABLE</div><div class="metric-value">${money(total)}</div><div class="metric-foot">Amount the shop owes suppliers</div></div><div class="card metric"><div class="metric-label">SUPPLIERS</div><div class="metric-value">${rows.length}</div><div class="metric-foot">Saved supplier accounts</div></div><div class="card"><div class="card-title">Quick payment</div><div class="card-subtitle">Record payment made to supplier</div><button class="btn btn-primary" style="margin-top:12px" data-action="supplier-payment">＋ Pay supplier</button></div></div><div class="card section"><div class="section-head"><div><div class="card-title">Supplier accounts</div><div class="card-subtitle">Purchases and payments are tracked in the ledger</div></div><div class="section-actions"><button class="btn btn-primary" data-action="add-supplier">＋ Add supplier</button></div></div><div class="searchbar"><input id="supplierSearch" class="input" placeholder="Search supplier or phone"></div><div id="suppliersTable" style="margin-top:14px">${suppliersTable(rows)}</div></div>`;
}
function suppliersTable(rows){if(!rows.length)return empty('🏭','No suppliers yet','Add suppliers to track purchase balances.');return `<div class="table-wrap"><table class="table"><thead><tr><th>Supplier</th><th>Phone</th><th>Address</th><th>Payable</th><th></th></tr></thead><tbody>${rows.map(c=>{const b=supplierBalance(c.id);return `<tr><td><button class="link-btn" data-action="view-supplier" data-id="${c.id}">${esc(c.name)}</button></td><td>${esc(c.phone||'—')}</td><td>${esc(c.address||'—')}</td><td class="money ${b>0?'text-danger':'text-good'}">${money(b)}</td><td class="nowrap"><button class="btn btn-outline btn-small" data-action="supplier-payment" data-id="${c.id}">Payment</button> <button class="btn btn-outline btn-small" data-action="edit-supplier" data-id="${c.id}">Edit</button></td></tr>`}).join('')}</tbody></table></div>`;}
function supplierForm(c={}){return `<form id="supplierForm"><div class="form-grid"><div class="field span-6"><label>Name *</label><input class="input" name="name" required value="${esc(c.name||'')}"></div><div class="field span-6"><label>Phone</label><input class="input" name="phone" value="${esc(c.phone||'')}"></div><div class="field span-8"><label>Address</label><input class="input" name="address" value="${esc(c.address||'')}"></div><div class="field span-4"><label>Opening payable</label><input class="input" name="openingBalance" type="number" step="0.01" value="${c.id?0:n(c.openingBalance)}" ${c.id?'disabled':''}></div><div class="field span-12"><label>Notes</label><textarea class="textarea" name="notes">${esc(c.notes||'')}</textarea></div></div><input type="hidden" name="id" value="${esc(c.id||'')}"></form>`;}

function renderCashbook(){
  const cashRows=state.cashEntries.slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt)); const expenses=state.expenses.filter(e=>e.status!=='reversed').slice().sort((a,b)=>b.createdAt.localeCompare(a.createdAt));
  qs('#main').innerHTML=`<div class="grid grid-4"><div class="card metric"><div class="metric-label">NET FUNDS</div><div class="metric-value">${money(cashBalance())}</div><div class="metric-foot">All methods combined</div></div><div class="card metric"><div class="metric-label">CASH</div><div class="metric-value">${money(cashBalance('Cash'))}</div><div class="metric-foot">Cash-only movement</div></div><div class="card metric"><div class="metric-label">BANK</div><div class="metric-value">${money(cashBalance('Bank'))}</div><div class="metric-foot">Bank transfers</div></div><div class="card"><div class="card-title">Quick entry</div><div class="card-subtitle">Record other income or money taken out</div><button class="btn btn-primary" style="margin-top:10px" data-action="manual-cash">＋ Cash entry</button></div></div><div class="card section"><div class="tabs"><button class="tab ${currentTabs.cashbook==='cash'?'active':''}" data-tab="cashbook" data-value="cash">Cashbook</button><button class="tab ${currentTabs.cashbook==='expenses'?'active':''}" data-tab="cashbook" data-value="expenses">Expenses</button></div>${currentTabs.cashbook==='cash'?`<div class="section-head"><div><div class="card-title">All money movement</div><div class="card-subtitle">Sales, purchases, collections, supplier payments and manual entries</div></div><div class="section-actions"><button class="btn btn-primary" data-action="manual-cash">＋ Entry</button></div></div>${cashTable(cashRows)}`:`<div class="section-head"><div><div class="card-title">Business expenses</div><div class="card-subtitle">Rent, salary, electricity, transport and other operating costs</div></div><div class="section-actions"><button class="btn btn-primary" data-action="add-expense">＋ Expense</button></div></div>${expensesTable(expenses)}`}</div>`;
}
function cashTable(rows){if(!rows.length)return empty('💵','No cash entries yet');return `<div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Type</th><th>Category</th><th>Reference</th><th>Method</th><th class="text-right">Amount</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dateFmt(x.date)}</td><td>${badge(x.direction==='in'?'IN':'OUT',x.direction==='in'?'good':'danger')}</td><td>${esc(x.category||'')}</td><td>${esc(x.reference||'')}<div class="muted">${esc(x.note||'')}</div></td><td>${esc(x.method||'')}</td><td class="money text-right ${x.direction==='in'?'text-good':'text-danger'}">${x.direction==='in'?'+':'-'}${money(x.amount)}</td></tr>`).join('')}</tbody></table></div>`;}
function expensesTable(rows){if(!rows.length)return empty('🧮','No expenses yet');return `<div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Category</th><th>Description</th><th>Method</th><th class="text-right">Amount</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dateFmt(x.date)}</td><td>${esc(x.category)}</td><td>${esc(x.description||'')}</td><td>${esc(x.paymentMethod||'')}</td><td class="money text-right">${money(x.amount)}</td></tr>`).join('')}</tbody></table></div>`;}

function reportData(from,to){
  const sales=activeSales().filter(s=>inRange(s.date,from,to)); const purchases=activePurchases().filter(p=>inRange(p.date,from,to)); const expenses=state.expenses.filter(e=>e.status!=='reversed'&&inRange(e.date,from,to)); const revenue=round2(sales.reduce((a,s)=>a+n(s.total),0)); const cogs=round2(sales.flatMap(s=>s.items||[]).reduce((a,i)=>a+n(i.qty)*n(i.costAtSale),0)); const exp=round2(expenses.reduce((a,e)=>a+n(e.amount),0)); const purchasesTotal=round2(purchases.reduce((a,p)=>a+n(p.total),0));
  const productMap={}; for(const s of sales) for(const i of s.items||[]){ const p=productById(i.productId); const k=i.productId; if(!productMap[k])productMap[k]={name:p?.name||i.name||'Product',qty:0,revenue:0,profit:0}; productMap[k].qty+=n(i.qty); productMap[k].revenue+=n(i.qty)*n(i.price); productMap[k].profit+=n(i.qty)*(n(i.price)-n(i.costAtSale)); }
  return {sales,purchases,expenses,revenue,cogs,gross:revenue-cogs,expenseTotal:exp,net:revenue-cogs-exp,purchasesTotal,top:Object.values(productMap).sort((a,b)=>b.revenue-a.revenue)};
}
function renderReports(){
  const {from,to}=monthRange(); const r=reportData(from,to); const stockValue=round2(state.products.reduce((s,p)=>s+n(p.stock)*n(p.costPrice),0)); const receivables=round2(state.customers.reduce((s,c)=>s+Math.max(0,customerBalance(c.id)),0)); const payables=round2(state.suppliers.reduce((s,c)=>s+Math.max(0,supplierBalance(c.id)),0));
  qs('#main').innerHTML=`<div class="card no-print"><div class="section-head"><div><div class="card-title">Report period</div><div class="card-subtitle">Choose any date range</div></div><div class="section-actions"><button class="btn btn-outline" data-action="report-today">Today</button><button class="btn btn-outline" data-action="report-month">This month</button><button class="btn btn-outline" data-action="export-report">Export CSV</button><button class="btn btn-primary" data-action="print-page">Print report</button></div></div><div class="form-grid"><div class="field span-3"><label>From</label><input id="reportFrom" class="input" type="date" value="${from}"></div><div class="field span-3"><label>To</label><input id="reportTo" class="input" type="date" value="${to}"></div></div></div><div id="reportBody">${reportBodyHTML(r,from,to,stockValue,receivables,payables)}</div>`;
}
function reportBodyHTML(r,from,to,stockValue,receivables,payables){ const max=Math.max(1,...r.top.slice(0,8).map(x=>x.revenue)); return `<div class="grid grid-5 section"><div class="card metric"><div class="metric-label">SALES</div><div class="metric-value">${money(r.revenue)}</div><div class="metric-foot">${r.sales.length} invoice(s)</div></div><div class="card metric"><div class="metric-label">COGS</div><div class="metric-value">${money(r.cogs)}</div><div class="metric-foot">Cost of goods sold</div></div><div class="card metric good"><div class="metric-label">GROSS PROFIT</div><div class="metric-value">${money(r.gross)}</div><div class="metric-foot">Sales minus COGS</div></div><div class="card metric danger"><div class="metric-label">EXPENSES</div><div class="metric-value">${money(r.expenseTotal)}</div><div class="metric-foot">Operating expenses</div></div><div class="card metric ${r.net>=0?'good':'danger'}"><div class="metric-label">NET PROFIT</div><div class="metric-value">${money(r.net)}</div><div class="metric-foot">Gross profit minus expenses</div></div></div><div class="grid grid-2 section"><div class="card"><div class="card-title">Profit & loss</div><div class="card-subtitle">${dateFmt(from)} — ${dateFmt(to)}</div><div class="stack" style="margin-top:14px"><div class="total-line"><span>Sales revenue</span><strong>${money(r.revenue)}</strong></div><div class="total-line"><span>Less: cost of goods sold</span><strong>(${money(r.cogs)})</strong></div><div class="total-line"><span>Gross profit</span><strong>${money(r.gross)}</strong></div><div class="total-line"><span>Less: operating expenses</span><strong>(${money(r.expenseTotal)})</strong></div><div class="total-line grand"><span>Net profit</span><span class="${r.net>=0?'text-good':'text-danger'}">${money(r.net)}</span></div><div class="divider"></div><div class="total-line"><span>Purchases in period</span><strong>${money(r.purchasesTotal)}</strong></div></div></div><div class="card"><div class="card-title">Current position</div><div class="card-subtitle">Balance figures as of now</div><div class="stack" style="margin-top:14px"><div class="total-line"><span>Inventory at cost</span><strong>${money(stockValue)}</strong></div><div class="total-line"><span>Customer receivables</span><strong class="text-warn">${money(receivables)}</strong></div><div class="total-line"><span>Supplier payables</span><strong class="text-danger">${money(payables)}</strong></div><div class="total-line"><span>Recorded funds balance</span><strong>${money(cashBalance())}</strong></div></div></div></div><div class="grid grid-2 section"><div class="card"><div class="card-title">Top products by sales</div><div class="card-subtitle">For selected date range</div><div style="margin-top:14px">${r.top.length?r.top.slice(0,8).map(x=>`<div class="bar-row"><div class="bar-label" title="${esc(x.name)}">${esc(x.name)}</div><div class="bar-track"><div class="bar-fill" style="width:${clamp(x.revenue/max*100,2,100)}%"></div></div><div class="bar-value">${money(x.revenue)}</div></div>`).join(''):empty('📊','No sales in this period')}</div></div><div class="card"><div class="card-title">Sales summary</div><div class="card-subtitle">Payments and invoice averages</div><div class="stack" style="margin-top:14px"><div class="total-line"><span>Invoices</span><strong>${r.sales.length}</strong></div><div class="total-line"><span>Average invoice</span><strong>${money(r.sales.length?r.revenue/r.sales.length:0)}</strong></div><div class="total-line"><span>Paid at sale</span><strong>${money(r.sales.reduce((s,x)=>s+n(x.paidAmount),0))}</strong></div><div class="total-line"><span>Credit created</span><strong>${money(r.sales.reduce((s,x)=>s+n(x.creditAmount),0))}</strong></div></div></div></div>`; }

function renderSettings(){
  qs('#main').innerHTML=`<div class="grid grid-2"><div class="card"><div class="card-title">Shop profile</div><div class="card-subtitle">Shown on printed receipts</div><form id="settingsForm" style="margin-top:14px"><div class="form-grid"><div class="field span-8"><label>Shop name</label><input class="input" name="shopName" value="${esc(state.settings.shopName)}"></div><div class="field span-4"><label>Owner name</label><input class="input" name="ownerName" value="${esc(state.settings.ownerName)}"></div><div class="field span-6"><label>Phone</label><input class="input" name="phone" value="${esc(state.settings.phone)}"></div><div class="field span-6"><label>WhatsApp</label><input class="input" name="whatsapp" value="${esc(state.settings.whatsapp)}"></div><div class="field span-12"><label>Address</label><textarea class="textarea" name="address">${esc(state.settings.address)}</textarea></div><div class="field span-4"><label>Invoice prefix</label><input class="input" name="invoicePrefix" value="${esc(state.settings.invoicePrefix)}"></div><div class="field span-4"><label>Purchase prefix</label><input class="input" name="purchasePrefix" value="${esc(state.settings.purchasePrefix)}"></div><div class="field span-4"><label>Default low stock</label><input class="input" name="lowStockDefault" type="number" min="0" value="${n(state.settings.lowStockDefault)}"></div></div><div class="form-actions"><button class="btn btn-primary" type="submit">Save settings</button></div></form></div><div class="card"><div class="card-title">Security</div><div class="card-subtitle">Optional PIN lock for this device</div><form id="pinForm" style="margin-top:14px"><div class="field span-12"><label><input type="checkbox" name="pinEnabled" ${state.settings.pinEnabled?'checked':''}> Enable PIN lock on startup</label></div><div class="field span-12" style="margin-top:12px"><label>New PIN</label><input class="input" name="adminPin" type="password" inputmode="numeric" minlength="4" maxlength="12" placeholder="Leave blank to keep current PIN"></div><div class="form-actions"><button class="btn btn-primary" type="submit">Save security</button></div></form><div class="divider"></div><div class="alert alert-info">The PIN prevents casual access on this browser. It is not a replacement for full server-side user authentication.</div></div></div><div class="grid grid-2 section"><div class="card"><div class="card-title">Backup & restore</div><div class="card-subtitle">Export the complete shop database to a JSON file</div><div class="stack" style="margin-top:14px"><button class="btn btn-primary" data-action="export-backup">⬇ Download full backup</button><button class="btn btn-outline" data-action="restore-backup">⬆ Restore from backup</button><button class="btn btn-outline" data-action="export-products">Export products CSV</button></div><div class="alert alert-warn" style="margin-top:14px">Keep backup files on another device, Google Drive, USB or email. Browser data can be lost if site data is cleared.</div></div><div class="card"><div class="card-title">Data tools</div><div class="card-subtitle">Useful when setting up the shop</div><div class="stack" style="margin-top:14px"><button class="btn btn-outline" data-action="import-products">Import products CSV</button><button class="btn btn-outline" data-action="load-demo">Load sample products & transactions</button><button class="btn btn-outline" data-action="view-audit">View recent audit log</button></div><div class="danger-zone" style="margin-top:18px"><strong>Danger zone</strong><div class="muted" style="margin:5px 0 10px">Deletes all products, sales, purchases and ledgers from this device.</div><button class="btn btn-danger" data-action="reset-data">Delete all shop data</button></div></div></div>`;
}

function addCashEntry({date=todayISO(),direction,category,amount,method='Cash',reference='',note='',sourceType='',sourceId=''}){ if(n(amount)<=0)return; state.cashEntries.unshift({id:uid('cash'),date,direction,category,amount:round2(amount),method,reference,note,sourceType,sourceId,createdAt:nowISO()}); }
function saveSale(){
  if(!posCart.length){toast('Cart is empty','warn');return}
  const customerId=qs('#posCustomer')?.value||''; const method=qs('#posMethod')?.value||'Cash'; const t=posTotals();
  if(t.credit>0&&!customerId){toast('Select a customer for credit / udhaar sale','warn');return}
  for(const line of posCart){const p=productById(line.productId);if(!p||n(line.qty)<=0){toast('Invalid product quantity','danger');return}if(n(line.qty)>n(p.stock)){toast(`${p.name}: only ${p.stock} in stock`,'danger');return}}
  const number=saleNo(); const items=posCart.map(x=>{const p=productById(x.productId);return {productId:p.id,name:p.name,sku:p.sku||'',qty:round2(x.qty),price:round2(x.price),costAtSale:round2(p.costPrice)}});
  const sale={id:uid('sale'),number,date:todayISO(),customerId,paymentMethod:method,subtotal:t.subtotal,discount:t.discount,total:t.total,paidAmount:t.paid,creditAmount:t.credit,items,status:'completed',createdAt:nowISO()};
  state.sales.unshift(sale); for(const i of items){const p=productById(i.productId);p.stock=round2(n(p.stock)-n(i.qty));p.updatedAt=nowISO();}
  if(t.paid>0)addCashEntry({direction:'in',category:'Sale',amount:t.paid,method,reference:number,sourceType:'sale',sourceId:sale.id});
  if(t.credit>0)state.customerLedger.unshift({id:uid('cl'),customerId,date:sale.date,type:'sale_credit',amount:t.credit,reference:number,note:'Credit sale',sourceId:sale.id,createdAt:nowISO()});
  audit('Sale completed',`${number} · ${money(t.total)}`); queueSave(); posCart=[]; toast(`${number} saved successfully`); showSaleModal(sale.id,true); if(currentPage==='pos')renderPOS();
}
function savePurchase(){
  if(!purchaseCart.length){toast('Purchase cart is empty','warn');return}
  const supplierId=qs('#purchaseSupplier')?.value||''; const date=qs('#purchaseDate')?.value||todayISO(); const supplierInvoice=qs('#supplierInvoice')?.value.trim()||''; const method=qs('#purchaseMethod')?.value||'Cash'; const total=round2(purchaseCart.reduce((s,x)=>s+n(x.qty)*n(x.cost),0)); const paid=clamp(n(qs('#purchasePaid')?.value),0,total); const credit=round2(total-paid); if(credit>0&&!supplierId){toast('Select a supplier for an unpaid purchase balance','warn');return}
  for(const x of purchaseCart)if(n(x.qty)<=0||n(x.cost)<0){toast('Invalid purchase line','danger');return}
  const number=purchaseNo(); const items=purchaseCart.map(x=>{const p=productById(x.productId);return {productId:p.id,name:p.name,sku:p.sku||'',qty:round2(x.qty),cost:round2(x.cost)}}); const purchase={id:uid('pur'),number,date,supplierId,supplierInvoice,paymentMethod:method,total,paidAmount:paid,creditAmount:credit,items,status:'completed',createdAt:nowISO()}; state.purchases.unshift(purchase);
  for(const i of items){const p=productById(i.productId);const oldQty=n(p.stock), oldCost=n(p.costPrice), addQty=n(i.qty); const newQty=oldQty+addQty; p.costPrice=newQty>0?round2((oldQty*oldCost+addQty*n(i.cost))/newQty):n(i.cost);p.stock=round2(newQty);p.updatedAt=nowISO();}
  if(paid>0)addCashEntry({date,direction:'out',category:'Purchase',amount:paid,method,reference:number,sourceType:'purchase',sourceId:purchase.id}); if(credit>0)state.supplierLedger.unshift({id:uid('sl'),supplierId,date,type:'purchase_credit',amount:credit,reference:number,note:'Unpaid purchase balance',sourceId:purchase.id,createdAt:nowISO()});
  audit('Purchase saved',`${number} · ${money(total)}`); queueSave(); purchaseCart=[]; toast(`${number} saved and stock updated`); renderPurchases();
}

function showProductModal(p){modal(p?'Edit product':'Add product',productForm(p),`<button class="btn btn-outline" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="save-product">Save product</button>`);}
function saveProduct(){const f=qs('#productForm');if(!f?.reportValidity())return;const d=Object.fromEntries(new FormData(f).entries());const existing=d.id?productById(d.id):null;const duplicate=state.products.find(x=>x.id!==d.id&&d.sku&&x.sku&&x.sku.toLowerCase()===d.sku.toLowerCase());if(duplicate){toast('That SKU is already used by another product','warn');return}const obj={...(existing||{}),id:existing?.id||uid('prod'),name:d.name.trim(),sku:d.sku.trim(),barcode:d.barcode.trim(),category:d.category.trim(),brand:d.brand.trim(),unit:d.unit,costPrice:round2(d.costPrice),salePrice:round2(d.salePrice),stock:round2(d.stock),minStock:round2(d.minStock),notes:d.notes.trim(),active:true,updatedAt:nowISO(),createdAt:existing?.createdAt||nowISO()};if(existing)Object.assign(existing,obj);else state.products.push(obj);audit(existing?'Product edited':'Product added',obj.name);queueSave();closeModal();toast('Product saved');renderProducts();}
function stockAdjustModal(id){const p=productById(id);if(!p)return;modal('Adjust stock',`<div class="alert alert-info">Use this only for physical count corrections, damaged goods or opening stock. Normal purchases and sales update stock automatically.</div><form id="stockAdjustForm" style="margin-top:14px"><div class="form-grid"><div class="field span-6"><label>Product</label><input class="input" disabled value="${esc(p.name)}"></div><div class="field span-3"><label>Current stock</label><input class="input" disabled value="${p.stock}"></div><div class="field span-3"><label>New stock *</label><input class="input" name="newStock" type="number" step="0.01" required value="${p.stock}"></div><div class="field span-12"><label>Reason *</label><input class="input" name="reason" required placeholder="Physical count, damaged, opening balance…"></div></div></form>`,`<button class="btn btn-outline" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="save-stock-adjust" data-id="${id}">Save adjustment</button>`);}
function saveStockAdjust(id){const f=qs('#stockAdjustForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f).entries());const p=productById(id);const old=p.stock;p.stock=round2(d.newStock);audit('Stock adjusted',`${p.name}: ${old} → ${p.stock} (${d.reason})`);queueSave();closeModal();toast('Stock adjusted');renderProducts();}

function customerModal(c){modal(c?'Edit customer':'Add customer',customerForm(c),`<button class="btn btn-outline" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="save-customer">Save customer</button>`);}
function saveCustomer(){const f=qs('#customerForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f).entries());let c=d.id?customerById(d.id):null;if(c){Object.assign(c,{name:d.name.trim(),phone:d.phone.trim(),address:d.address.trim(),notes:d.notes.trim(),updatedAt:nowISO()});}else{c={id:uid('cust'),name:d.name.trim(),phone:d.phone.trim(),address:d.address.trim(),notes:d.notes.trim(),active:true,createdAt:nowISO()};state.customers.push(c);if(n(d.openingBalance)!==0)state.customerLedger.unshift({id:uid('cl'),customerId:c.id,date:todayISO(),type:'opening',amount:round2(d.openingBalance),reference:'OPENING',note:'Opening balance',createdAt:nowISO()});}audit(d.id?'Customer edited':'Customer added',c.name);queueSave();closeModal();toast('Customer saved');renderCustomers();}
function customerPaymentModal(customerId=''){modal('Receive customer payment',`<form id="customerPaymentForm"><div class="form-grid"><div class="field span-6"><label>Customer *</label><select class="select" name="customerId" required><option value="">Select customer</option>${state.customers.map(c=>`<option value="${c.id}" ${customerId===c.id?'selected':''}>${esc(c.name)} · Due ${money(customerBalance(c.id))}</option>`).join('')}</select></div><div class="field span-3"><label>Date</label><input class="input" name="date" type="date" value="${todayISO()}" required></div><div class="field span-3"><label>Amount *</label><input class="input" name="amount" type="number" min="0.01" step="0.01" required></div><div class="field span-4"><label>Method</label><select class="select" name="method"><option>Cash</option><option>Bank</option><option>EasyPaisa</option><option>JazzCash</option><option>Card</option><option>Other</option></select></div><div class="field span-8"><label>Note</label><input class="input" name="note" placeholder="Optional"></div></div></form>`,`<button class="btn btn-outline" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="save-customer-payment">Receive payment</button>`);}
function saveCustomerPayment(){const f=qs('#customerPaymentForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f).entries());const amount=round2(d.amount);const ref=`CR-${String(state.counters.customerPayment++).padStart(6,'0')}`;state.customerLedger.unshift({id:uid('cl'),customerId:d.customerId,date:d.date,type:'payment',amount:-amount,reference:ref,note:d.note.trim(),createdAt:nowISO()});addCashEntry({date:d.date,direction:'in',category:'Customer payment',amount,method:d.method,reference:ref,note:d.note,sourceType:'customer_payment'});audit('Customer payment received',`${customerById(d.customerId)?.name} · ${money(amount)}`);queueSave();closeModal();toast('Customer payment recorded');renderCustomers();}
function showCustomer(id){const c=customerById(id);if(!c)return;const rows=state.customerLedger.filter(x=>x.customerId===id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));modal(c.name,`<div class="grid grid-3"><div class="card metric warn"><div class="metric-label">CURRENT BALANCE</div><div class="metric-value">${money(customerBalance(id))}</div></div><div class="card"><div class="metric-label">PHONE</div><div class="strong" style="margin-top:8px">${esc(c.phone||'—')}</div></div><div class="card"><div class="metric-label">ADDRESS</div><div class="strong" style="margin-top:8px">${esc(c.address||'—')}</div></div></div><div class="section-head" style="margin-top:18px"><div class="card-title">Ledger</div><div class="section-actions"><button class="btn btn-primary btn-small" data-action="customer-payment" data-id="${id}">Receive payment</button></div></div>${ledgerTable(rows,'customer')}`,`<button class="btn btn-outline" data-action="close-modal">Close</button>`,true);}

function supplierModal(c){modal(c?'Edit supplier':'Add supplier',supplierForm(c),`<button class="btn btn-outline" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="save-supplier">Save supplier</button>`);}
function saveSupplier(){const f=qs('#supplierForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f).entries());let c=d.id?supplierById(d.id):null;if(c){Object.assign(c,{name:d.name.trim(),phone:d.phone.trim(),address:d.address.trim(),notes:d.notes.trim(),updatedAt:nowISO()});}else{c={id:uid('supp'),name:d.name.trim(),phone:d.phone.trim(),address:d.address.trim(),notes:d.notes.trim(),active:true,createdAt:nowISO()};state.suppliers.push(c);if(n(d.openingBalance)!==0)state.supplierLedger.unshift({id:uid('sl'),supplierId:c.id,date:todayISO(),type:'opening',amount:round2(d.openingBalance),reference:'OPENING',note:'Opening payable',createdAt:nowISO()});}audit(d.id?'Supplier edited':'Supplier added',c.name);queueSave();closeModal();toast('Supplier saved');renderSuppliers();}
function supplierPaymentModal(supplierId=''){modal('Pay supplier',`<form id="supplierPaymentForm"><div class="form-grid"><div class="field span-6"><label>Supplier *</label><select class="select" name="supplierId" required><option value="">Select supplier</option>${state.suppliers.map(c=>`<option value="${c.id}" ${supplierId===c.id?'selected':''}>${esc(c.name)} · Owed ${money(supplierBalance(c.id))}</option>`).join('')}</select></div><div class="field span-3"><label>Date</label><input class="input" name="date" type="date" value="${todayISO()}" required></div><div class="field span-3"><label>Amount *</label><input class="input" name="amount" type="number" min="0.01" step="0.01" required></div><div class="field span-4"><label>Method</label><select class="select" name="method"><option>Cash</option><option>Bank</option><option>EasyPaisa</option><option>JazzCash</option><option>Card</option><option>Other</option></select></div><div class="field span-8"><label>Note</label><input class="input" name="note" placeholder="Optional"></div></div></form>`,`<button class="btn btn-outline" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="save-supplier-payment">Save payment</button>`);}
function saveSupplierPayment(){const f=qs('#supplierPaymentForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f).entries());const amount=round2(d.amount);const ref=`SP-${String(state.counters.supplierPayment++).padStart(6,'0')}`;state.supplierLedger.unshift({id:uid('sl'),supplierId:d.supplierId,date:d.date,type:'payment',amount:-amount,reference:ref,note:d.note.trim(),createdAt:nowISO()});addCashEntry({date:d.date,direction:'out',category:'Supplier payment',amount,method:d.method,reference:ref,note:d.note,sourceType:'supplier_payment'});audit('Supplier payment made',`${supplierById(d.supplierId)?.name} · ${money(amount)}`);queueSave();closeModal();toast('Supplier payment recorded');renderSuppliers();}
function showSupplier(id){const c=supplierById(id);if(!c)return;const rows=state.supplierLedger.filter(x=>x.supplierId===id).sort((a,b)=>b.createdAt.localeCompare(a.createdAt));modal(c.name,`<div class="grid grid-3"><div class="card metric danger"><div class="metric-label">CURRENT PAYABLE</div><div class="metric-value">${money(supplierBalance(id))}</div></div><div class="card"><div class="metric-label">PHONE</div><div class="strong" style="margin-top:8px">${esc(c.phone||'—')}</div></div><div class="card"><div class="metric-label">ADDRESS</div><div class="strong" style="margin-top:8px">${esc(c.address||'—')}</div></div></div><div class="section-head" style="margin-top:18px"><div class="card-title">Ledger</div><div class="section-actions"><button class="btn btn-primary btn-small" data-action="supplier-payment" data-id="${id}">Pay supplier</button></div></div>${ledgerTable(rows,'supplier')}`,`<button class="btn btn-outline" data-action="close-modal">Close</button>`,true);}
function ledgerTable(rows,type){if(!rows.length)return empty('📒','No ledger entries');return `<div class="table-wrap"><table class="table"><thead><tr><th>Date</th><th>Reference</th><th>Type</th><th>Note</th><th class="text-right">Change</th></tr></thead><tbody>${rows.map(x=>`<tr><td>${dateFmt(x.date)}</td><td>${esc(x.reference||'')}</td><td>${esc(x.type.replaceAll('_',' '))}</td><td>${esc(x.note||'')}</td><td class="money text-right ${n(x.amount)>0?'text-warn':'text-good'}">${n(x.amount)>0?'+':''}${money(x.amount)}</td></tr>`).join('')}</tbody></table></div>`;}

function expenseModal(){modal('Add expense',`<form id="expenseForm"><div class="form-grid"><div class="field span-4"><label>Date</label><input class="input" type="date" name="date" value="${todayISO()}" required></div><div class="field span-4"><label>Category</label><select class="select" name="category"><option>Rent</option><option>Electricity</option><option>Salary</option><option>Transport</option><option>Delivery</option><option>Repair & Maintenance</option><option>Tea / Food</option><option>Internet / Phone</option><option>Tax / Fee</option><option>Other</option></select></div><div class="field span-4"><label>Amount *</label><input class="input" type="number" name="amount" min="0.01" step="0.01" required></div><div class="field span-4"><label>Payment method</label><select class="select" name="paymentMethod"><option>Cash</option><option>Bank</option><option>Card</option><option>EasyPaisa</option><option>JazzCash</option><option>Other</option></select></div><div class="field span-8"><label>Description</label><input class="input" name="description"></div></div></form>`,`<button class="btn btn-outline" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="save-expense">Save expense</button>`);}
function saveExpense(){const f=qs('#expenseForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f).entries());const e={id:uid('exp'),date:d.date,category:d.category,amount:round2(d.amount),paymentMethod:d.paymentMethod,description:d.description.trim(),status:'completed',createdAt:nowISO()};state.expenses.unshift(e);addCashEntry({date:e.date,direction:'out',category:`Expense: ${e.category}`,amount:e.amount,method:e.paymentMethod,reference:'EXP',note:e.description,sourceType:'expense',sourceId:e.id});audit('Expense added',`${e.category} · ${money(e.amount)}`);queueSave();closeModal();toast('Expense saved');renderCashbook();}
function cashModal(){modal('Manual cashbook entry',`<form id="cashForm"><div class="form-grid"><div class="field span-3"><label>Date</label><input class="input" type="date" name="date" value="${todayISO()}" required></div><div class="field span-3"><label>Direction</label><select class="select" name="direction"><option value="in">Money in</option><option value="out">Money out</option></select></div><div class="field span-3"><label>Method</label><select class="select" name="method"><option>Cash</option><option>Bank</option><option>Card</option><option>EasyPaisa</option><option>JazzCash</option><option>Other</option></select></div><div class="field span-3"><label>Amount *</label><input class="input" type="number" name="amount" min="0.01" step="0.01" required></div><div class="field span-4"><label>Category</label><input class="input" name="category" placeholder="Owner capital, withdrawal, refund…" required></div><div class="field span-4"><label>Reference</label><input class="input" name="reference"></div><div class="field span-4"><label>Note</label><input class="input" name="note"></div></div></form>`,`<button class="btn btn-outline" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="save-manual-cash">Save entry</button>`);}
function saveManualCash(){const f=qs('#cashForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f).entries());addCashEntry({date:d.date,direction:d.direction,category:d.category.trim(),amount:round2(d.amount),method:d.method,reference:d.reference.trim(),note:d.note.trim(),sourceType:'manual'});audit('Manual cashbook entry',`${d.direction} ${money(d.amount)} · ${d.category}`);queueSave();closeModal();toast('Cashbook entry saved');renderCashbook();}

function showSaleModal(id,afterSave=false){const s=state.sales.find(x=>x.id===id);if(!s)return;const c=customerById(s.customerId);const body=`<div class="receipt-preview"><h2>${esc(state.settings.shopName)}</h2><div class="receipt-center">${esc(state.settings.address||'')}</div><div class="receipt-center">${esc(state.settings.phone||'')}</div><div class="receipt-rule"></div><div class="receipt-line"><span>Invoice</span><strong>${esc(s.number)}</strong></div><div class="receipt-line"><span>Date</span><span>${dateFmt(s.date)}</span></div><div class="receipt-line"><span>Customer</span><span>${esc(c?.name||'Walk-in')}</span></div><div class="receipt-rule"></div>${(s.items||[]).map(i=>`<div style="margin:7px 0"><div class="strong" style="font-size:12px">${esc(i.name)}</div><div class="receipt-line"><span>${i.qty} × ${money(i.price)}</span><span>${money(n(i.qty)*n(i.price))}</span></div></div>`).join('')}<div class="receipt-rule"></div><div class="receipt-line"><span>Subtotal</span><span>${money(s.subtotal)}</span></div>${n(s.discount)>0?`<div class="receipt-line"><span>Discount</span><span>-${money(s.discount)}</span></div>`:''}<div class="receipt-line receipt-big"><span>TOTAL</span><span>${money(s.total)}</span></div><div class="receipt-line"><span>Paid</span><span>${money(s.paidAmount)}</span></div>${n(s.creditAmount)>0?`<div class="receipt-line"><span>Udhaar</span><span>${money(s.creditAmount)}</span></div>`:''}<div class="receipt-rule"></div><div class="receipt-center">Thank you</div></div>`;modal(afterSave?'Sale saved':'Invoice '+esc(s.number),body,`<button class="btn btn-outline" data-action="close-modal">Close</button><button class="btn btn-primary" data-action="print-sale" data-id="${s.id}">Print receipt</button>`);}
function printSale(id){const s=state.sales.find(x=>x.id===id);if(!s)return;const c=customerById(s.customerId);const w=window.open('','_blank','width=480,height=720'); if(!w){toast('Popup blocked. Allow popups to print.','warn');return} w.document.write(`<!doctype html><html><head><title>${esc(s.number)}</title><style>body{font-family:monospace;width:320px;margin:20px auto;color:#111}h2{text-align:center;margin:0}.c{text-align:center;font-size:12px}.r{display:flex;justify-content:space-between;gap:8px;margin:5px 0}.rule{border-top:1px dashed #333;margin:10px 0}.b{font-weight:bold;font-size:16px}.item{margin:7px 0}@media print{body{margin:0;width:100%}}</style></head><body><h2>${esc(state.settings.shopName)}</h2><div class="c">${esc(state.settings.address||'')}</div><div class="c">${esc(state.settings.phone||'')}</div><div class="rule"></div><div class="r"><span>Invoice</span><b>${esc(s.number)}</b></div><div class="r"><span>Date</span><span>${dateFmt(s.date)}</span></div><div class="r"><span>Customer</span><span>${esc(c?.name||'Walk-in')}</span></div><div class="rule"></div>${s.items.map(i=>`<div class="item"><b>${esc(i.name)}</b><div class="r"><span>${i.qty} x ${money(i.price)}</span><span>${money(n(i.qty)*n(i.price))}</span></div></div>`).join('')}<div class="rule"></div><div class="r"><span>Subtotal</span><span>${money(s.subtotal)}</span></div>${n(s.discount)>0?`<div class="r"><span>Discount</span><span>-${money(s.discount)}</span></div>`:''}<div class="r b"><span>TOTAL</span><span>${money(s.total)}</span></div><div class="r"><span>Paid</span><span>${money(s.paidAmount)}</span></div>${n(s.creditAmount)>0?`<div class="r"><span>Udhaar</span><span>${money(s.creditAmount)}</span></div>`:''}<div class="rule"></div><div class="c">Thank you</div><script>window.onload=()=>window.print()<\/script></body></html>`);w.document.close();}
function reverseSale(id){const s=state.sales.find(x=>x.id===id);if(!s||s.status==='reversed')return;confirmDialog('Return / reverse sale',`This will reverse <strong>${esc(s.number)}</strong>, put all items back into stock, reverse customer credit and record a refund of <strong>${money(s.paidAmount)}</strong>.`,()=>{for(const i of s.items){const p=productById(i.productId);if(p)p.stock=round2(n(p.stock)+n(i.qty));}if(n(s.paidAmount)>0)addCashEntry({date:todayISO(),direction:'out',category:'Sale return',amount:s.paidAmount,method:s.paymentMethod,reference:s.number,note:'Full sale return',sourceType:'sale_return',sourceId:s.id});if(n(s.creditAmount)>0&&s.customerId)state.customerLedger.unshift({id:uid('cl'),customerId:s.customerId,date:todayISO(),type:'sale_return',amount:-n(s.creditAmount),reference:s.number,note:'Credit reversed due to return',sourceId:s.id,createdAt:nowISO()});s.status='reversed';s.reversedAt=nowISO();audit('Sale reversed',s.number);queueSave();toast('Sale reversed and stock restored');renderSales();},true);}

function quickPriceModal(){modal('Quick price lookup',`<div class="quick-lookup"><input id="modalPriceSearch" class="input" placeholder="Product name, SKU or barcode" autofocus><button class="btn btn-primary" data-action="modal-price-search">Search</button></div><div id="modalLookupResult"></div>`,`<button class="btn btn-outline" data-action="close-modal">Close</button>`);setTimeout(()=>qs('#modalPriceSearch')?.focus(),50);}
function lookupHTML(q){const rows=productMatches(q,10);if(!q.trim())return '';if(!rows.length)return `<div style="margin-top:12px">${empty('🔎','No matching product')}</div>`;return rows.map(p=>`<div class="lookup-result"><div><div class="strong">${esc(p.name)}</div><div class="muted">${esc(p.sku||'')} · Stock ${p.stock} ${esc(p.unit||'')}</div></div><div class="lookup-price">${money(p.salePrice)}</div></div>`).join('');}

function exportBackup(){const payload={app:'Electrical Store Manager',version:APP_VERSION,exportedAt:nowISO(),state};downloadBlob(JSON.stringify(payload,null,2),`electrical-store-backup-${todayISO()}.json`,'application/json');state.settings.lastBackupAt=nowISO();queueSave();updateBrand();toast('Full backup downloaded');}
function restoreBackupModal(){modal('Restore full backup',`<div class="alert alert-warn">Restoring replaces the current database on this device. Export a backup of current data first if needed.</div><div style="margin-top:14px"><input id="restoreFile" class="file-input" type="file" accept="application/json,.json"></div>`,`<button class="btn btn-outline" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="confirm-restore">Restore backup</button>`);}
async function restoreBackup(){const file=qs('#restoreFile')?.files?.[0];if(!file){toast('Choose a backup file first','warn');return}try{const obj=JSON.parse(await file.text());const raw=obj.state||obj;if(!raw.products||!raw.sales){throw new Error('Invalid backup')}state=migrate(raw);await persist();closeModal();toast('Backup restored');setPage('dashboard');}catch(e){toast('Could not restore: invalid backup file','danger')}}
function downloadBlob(content,name,type='text/plain'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;document.body.appendChild(a);a.click();setTimeout(()=>{URL.revokeObjectURL(a.href);a.remove()},500);}
function exportProducts(){const headers=['sku','name','category','brand','unit','barcode','costPrice','salePrice','stock','minStock','notes'];const rows=[headers.join(','),...state.products.map(p=>headers.map(h=>csvCell(p[h]??'')).join(','))];downloadBlob(rows.join('\n'),`products-${todayISO()}.csv`,'text/csv');toast('Products CSV exported');}
function importProductsModal(){modal('Import products CSV',`<div class="alert alert-info">Columns supported: <strong>sku, name, category, brand, unit, barcode, costPrice, salePrice, stock, minStock, notes</strong>. Existing products with the same SKU will be updated.</div><div style="margin-top:14px"><input id="productsCsv" class="file-input" type="file" accept=".csv,text/csv"></div><div class="help" style="margin-top:8px">Use the Export Products button first if you want a sample structure.</div>`,`<button class="btn btn-outline" data-action="close-modal">Cancel</button><button class="btn btn-primary" data-action="confirm-import-products">Import products</button>`);}
function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i],next=text[i+1];if(c==='"'&&quoted&&next==='"'){cell+='"';i++;}else if(c==='"'){quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&next==='\n')i++;row.push(cell);if(row.some(v=>v.trim()!==''))rows.push(row);row=[];cell='';}else cell+=c;}row.push(cell);if(row.some(v=>v.trim()!==''))rows.push(row);return rows;}
async function importProducts(){const file=qs('#productsCsv')?.files?.[0];if(!file){toast('Choose a CSV file','warn');return}try{const rows=parseCSV(await file.text());if(rows.length<2)throw new Error();const headers=rows[0].map(x=>x.trim());let added=0,updated=0;for(const cells of rows.slice(1)){const d={};headers.forEach((h,i)=>d[h]=(cells[i]??'').trim());if(!d.name)continue;let p=d.sku?state.products.find(x=>String(x.sku).toLowerCase()===d.sku.toLowerCase()):null;const values={name:d.name,sku:d.sku||'',category:d.category||'',brand:d.brand||'',unit:d.unit||'pcs',barcode:d.barcode||'',costPrice:round2(d.costPrice),salePrice:round2(d.salePrice),stock:round2(d.stock),minStock:d.minStock===''?state.settings.lowStockDefault:round2(d.minStock),notes:d.notes||'',active:true,updatedAt:nowISO()};if(p){Object.assign(p,values);updated++;}else{state.products.push({id:uid('prod'),...values,createdAt:nowISO()});added++;}}audit('Products CSV imported',`${added} added, ${updated} updated`);queueSave();closeModal();toast(`${added} added, ${updated} updated`);if(currentPage==='products')renderProducts();}catch{toast('CSV could not be imported. Check its format.','danger')}}
function exportReport(){const from=qs('#reportFrom')?.value||monthRange().from,to=qs('#reportTo')?.value||todayISO(),r=reportData(from,to);const lines=[['Metric','Value'],['From',from],['To',to],['Sales revenue',r.revenue],['COGS',r.cogs],['Gross profit',r.gross],['Expenses',r.expenseTotal],['Net profit',r.net],['Purchases',r.purchasesTotal],[],['Top product','Qty','Revenue','Profit'],...r.top.map(x=>[x.name,x.qty,x.revenue,x.profit])].map(row=>row.map(csvCell).join(','));downloadBlob(lines.join('\n'),`report-${from}-to-${to}.csv`,'text/csv');toast('Report exported');}

function viewAudit(){modal('Recent audit log',state.audit.length?`<div class="table-wrap"><table class="table"><thead><tr><th>Time</th><th>Action</th><th>Details</th></tr></thead><tbody>${state.audit.slice(0,100).map(a=>`<tr><td>${dateTimeFmt(a.at)}</td><td>${esc(a.action)}</td><td>${esc(a.details)}</td></tr>`).join('')}</tbody></table></div>`:empty('📝','No audit entries'),`<button class="btn btn-outline" data-action="close-modal">Close</button>`,true);}
function loadDemo(){confirmDialog('Load sample data','This adds sample products, customers, suppliers and a few transactions so you can explore the system. It does not delete existing data.',()=>{const p1={id:uid('prod'),name:'LED Bulb 12W',sku:'LED-12W',category:'Lighting',brand:'Philips',unit:'pcs',barcode:'',costPrice:420,salePrice:550,stock:36,minStock:8,notes:'',active:true,createdAt:nowISO()};const p2={id:uid('prod'),name:'1.5mm Copper Wire',sku:'WIRE-15',category:'Wire',brand:'Pakistan Cables',unit:'roll',barcode:'',costPrice:8200,salePrice:9400,stock:8,minStock:3,notes:'',active:true,createdAt:nowISO()};const p3={id:uid('prod'),name:'10A Switch',sku:'SW-10A',category:'Switches',brand:'Schneider',unit:'pcs',barcode:'',costPrice:260,salePrice:350,stock:60,minStock:12,notes:'',active:true,createdAt:nowISO()};state.products.push(p1,p2,p3);const c={id:uid('cust'),name:'Ali Electrician',phone:'0300 1234567',address:'Local market',notes:'',active:true,createdAt:nowISO()};state.customers.push(c);const s={id:uid('supp'),name:'Lahore Electrical Traders',phone:'042 1234567',address:'Hall Road, Lahore',notes:'',active:true,createdAt:nowISO()};state.suppliers.push(s);audit('Demo data loaded','3 products, customer and supplier');queueSave();toast('Sample data loaded');renderSettings();});}
function resetData(){confirmDialog('Delete all shop data','This will permanently delete products, sales, purchases, expenses, customers, suppliers and ledgers from this browser.',async()=>{const keep={...state.settings,shopName:state.settings.shopName,address:state.settings.address,phone:state.settings.phone,ownerName:state.settings.ownerName,pinEnabled:state.settings.pinEnabled,adminPin:state.settings.adminPin};state=DEFAULT_STATE();state.settings={...state.settings,...keep,lastBackupAt:null};await persist();posCart=[];purchaseCart=[];toast('All shop data deleted');setPage('dashboard');},true);}

function refreshReport(){const from=qs('#reportFrom')?.value||monthRange().from,to=qs('#reportTo')?.value||todayISO(),r=reportData(from,to);const stockValue=round2(state.products.reduce((s,p)=>s+n(p.stock)*n(p.costPrice),0));const receivables=round2(state.customers.reduce((s,c)=>s+Math.max(0,customerBalance(c.id)),0));const payables=round2(state.suppliers.reduce((s,c)=>s+Math.max(0,supplierBalance(c.id)),0));qs('#reportBody').innerHTML=reportBodyHTML(r,from,to,stockValue,receivables,payables);}
function filterProducts(){const q=qs('#productSearch')?.value.toLowerCase()||'',f=qs('#productStockFilter')?.value||'all';let rows=state.products.filter(p=>[p.name,p.sku,p.barcode,p.category,p.brand].some(v=>String(v||'').toLowerCase().includes(q)));if(f==='low')rows=rows.filter(p=>n(p.stock)<=n(p.minStock));if(f==='out')rows=rows.filter(p=>n(p.stock)<=0);qs('#productsTable').innerHTML=productsTable(rows.sort((a,b)=>a.name.localeCompare(b.name)));}
function filterSales(){const q=qs('#salesSearch')?.value.toLowerCase()||'',from=qs('#salesFrom')?.value||'',to=qs('#salesTo')?.value||'';let rows=state.sales.filter(s=>inRange(s.date,from,to)&&[s.number,customerById(s.customerId)?.name,...(s.items||[]).map(i=>i.name)].some(v=>String(v||'').toLowerCase().includes(q)));qs('#salesTable').innerHTML=salesTable(rows.sort((a,b)=>b.createdAt.localeCompare(a.createdAt)));}
function filterCustomers(){const q=qs('#customerSearch')?.value.toLowerCase()||'';const rows=state.customers.filter(c=>[c.name,c.phone,c.address].some(v=>String(v||'').toLowerCase().includes(q)));qs('#customersTable').innerHTML=customersTable(rows);}
function filterSuppliers(){const q=qs('#supplierSearch')?.value.toLowerCase()||'';const rows=state.suppliers.filter(c=>[c.name,c.phone,c.address].some(v=>String(v||'').toLowerCase().includes(q)));qs('#suppliersTable').innerHTML=suppliersTable(rows);}

function saveSettingsForm(){const f=qs('#settingsForm');const d=Object.fromEntries(new FormData(f).entries());Object.assign(state.settings,{shopName:d.shopName.trim()||'Electrical Store',ownerName:d.ownerName.trim(),phone:d.phone.trim(),whatsapp:d.whatsapp.trim(),address:d.address.trim(),invoicePrefix:(d.invoicePrefix.trim()||'INV').toUpperCase(),purchasePrefix:(d.purchasePrefix.trim()||'PUR').toUpperCase(),lowStockDefault:round2(d.lowStockDefault)});audit('Settings updated','Shop profile');queueSave();updateBrand();toast('Settings saved');}
function savePinForm(){const f=qs('#pinForm');const fd=new FormData(f);const enabled=fd.get('pinEnabled')==='on',pin=(fd.get('adminPin')||'').trim();if(enabled&&!state.settings.adminPin&&!pin){toast('Enter a PIN to enable the lock','warn');return}if(pin&&pin.length<4){toast('PIN must be at least 4 digits','warn');return}state.settings.pinEnabled=enabled;if(pin)state.settings.adminPin=pin;if(!enabled)state.settings.pinEnabled=false;audit('Security settings updated',enabled?'PIN enabled':'PIN disabled');queueSave();toast('Security settings saved');renderSettings();}

function lockApp(){if(!state.settings.pinEnabled||!state.settings.adminPin){toast('Enable a PIN in Settings first','warn');return}showLockScreen();}
function showLockScreen(){qs('#appShell').classList.add('hidden');const s=qs('#startup');s.classList.remove('hidden');qs('#startupText').textContent=`${state.settings.shopName} is locked`;qs('#startupControls').innerHTML=`<div class="pin-row"><input id="unlockPin" class="input" type="password" inputmode="numeric" maxlength="12" placeholder="PIN"><button class="btn btn-primary" data-action="unlock-app">Unlock</button></div><div class="help" style="margin-top:10px">Enter the shop PIN</div>`;setTimeout(()=>qs('#unlockPin')?.focus(),80);}
function unlockApp(){if((qs('#unlockPin')?.value||'')===state.settings.adminPin){qs('#startup').classList.add('hidden');qs('#appShell').classList.remove('hidden');toast('Unlocked');}else{toast('Incorrect PIN','danger');}}

function bindGlobalEvents(){
  document.addEventListener('click',e=>{
    const nav=e.target.closest('[data-nav]');
    if(nav){ setPage(nav.dataset.nav); return; }
    const tab=e.target.closest('[data-tab]');
    if(tab){ currentTabs[tab.dataset.tab]=tab.dataset.value; renderPage(); return; }
    const btn=e.target.closest('[data-action]');
    if(!btn) return;
    const a=btn.dataset.action, id=btn.dataset.id;
    if(a==='close-modal'){ closeModal(); }
    else if(a==='close-modal-bg'&&e.target===btn){ closeModal(); }
    else if(a==='quick-price'){ quickPriceModal(); }
    else if(a==='dashboard-price-search'){ qs('#dashLookupResult').innerHTML=lookupHTML(qs('#dashPriceSearch').value); }
    else if(a==='modal-price-search'){ qs('#modalLookupResult').innerHTML=lookupHTML(qs('#modalPriceSearch').value); }
    else if(a==='add-pos-product'){
      const p=productById(id); if(!p) return; const ex=posCart.find(x=>x.productId===id);
      if(ex) ex.qty=round2(ex.qty+1); else posCart.push({productId:id,qty:1,price:p.salePrice}); updatePOSCartUI();
    }
    else if(a==='remove-pos-line'){ posCart.splice(+btn.dataset.index,1); updatePOSCartUI(); }
    else if(a==='clear-pos-cart'){ posCart=[]; updatePOSCartUI(); }
    else if(a==='complete-sale'){ saveSale(); }
    else if(a==='add-product'){ showProductModal(); }
    else if(a==='edit-product'){ showProductModal(productById(id)); }
    else if(a==='save-product'){ saveProduct(); }
    else if(a==='adjust-stock'){ stockAdjustModal(id); }
    else if(a==='save-stock-adjust'){ saveStockAdjust(id); }
    else if(a==='import-products'){ importProductsModal(); }
    else if(a==='confirm-import-products'){ importProducts(); }
    else if(a==='export-products'){ exportProducts(); }
    else if(a==='add-purchase-product'){
      const p=productById(id); if(!p) return; const ex=purchaseCart.find(x=>x.productId===id);
      if(ex) ex.qty=round2(ex.qty+1); else purchaseCart.push({productId:id,qty:1,cost:p.costPrice}); updatePurchaseUI();
    }
    else if(a==='remove-purchase-line'){ purchaseCart.splice(+btn.dataset.index,1); updatePurchaseUI(); }
    else if(a==='clear-purchase-cart'){ purchaseCart=[]; updatePurchaseUI(); }
    else if(a==='complete-purchase'){ savePurchase(); }
    else if(a==='view-sale'){ showSaleModal(id); }
    else if(a==='print-sale'){ printSale(id); }
    else if(a==='reverse-sale'){ reverseSale(id); }
    else if(a==='add-customer'){ customerModal(); }
    else if(a==='edit-customer'){ customerModal(customerById(id)); }
    else if(a==='save-customer'){ saveCustomer(); }
    else if(a==='customer-payment'){ customerPaymentModal(id||''); }
    else if(a==='save-customer-payment'){ saveCustomerPayment(); }
    else if(a==='view-customer'){ showCustomer(id); }
    else if(a==='add-supplier'){ supplierModal(); }
    else if(a==='edit-supplier'){ supplierModal(supplierById(id)); }
    else if(a==='save-supplier'){ saveSupplier(); }
    else if(a==='supplier-payment'){ supplierPaymentModal(id||''); }
    else if(a==='save-supplier-payment'){ saveSupplierPayment(); }
    else if(a==='view-supplier'){ showSupplier(id); }
    else if(a==='add-expense'){ expenseModal(); }
    else if(a==='save-expense'){ saveExpense(); }
    else if(a==='manual-cash'){ cashModal(); }
    else if(a==='save-manual-cash'){ saveManualCash(); }
    else if(a==='report-today'){ qs('#reportFrom').value=todayISO(); qs('#reportTo').value=todayISO(); refreshReport(); }
    else if(a==='report-month'){ const m=monthRange(); qs('#reportFrom').value=m.from; qs('#reportTo').value=m.to; refreshReport(); }
    else if(a==='export-report'){ exportReport(); }
    else if(a==='print-page'){ window.print(); }
    else if(a==='export-backup'){ exportBackup(); }
    else if(a==='restore-backup'){ restoreBackupModal(); }
    else if(a==='confirm-restore'){ restoreBackup(); }
    else if(a==='view-audit'){ viewAudit(); }
    else if(a==='load-demo'){ loadDemo(); }
    else if(a==='reset-data'){ resetData(); }
    else if(a==='lock-app'){ lockApp(); }
    else if(a==='unlock-app'){ unlockApp(); }
  });
  document.addEventListener('input',e=>{
    if(e.target.id==='posSearch') qs('#posResults').innerHTML=posProductTiles(productMatches(e.target.value));
    else if(e.target.matches('[data-cart-qty]')){ const i=+e.target.dataset.cartQty; posCart[i].qty=Math.max(.01,n(e.target.value)); updatePOSTotals(); }
    else if(e.target.matches('[data-cart-price]')){ const i=+e.target.dataset.cartPrice; posCart[i].price=Math.max(0,n(e.target.value)); updatePOSTotals(); }
    else if(e.target.id==='posDiscount'||e.target.id==='posPaid') updatePOSTotals();
    else if(e.target.id==='purchaseSearch') qs('#purchaseResults').innerHTML=purchaseProductTiles(productMatches(e.target.value));
    else if(e.target.matches('[data-purchase-qty]')){ purchaseCart[+e.target.dataset.purchaseQty].qty=Math.max(.01,n(e.target.value)); updatePurchaseUI(); }
    else if(e.target.matches('[data-purchase-cost]')){ purchaseCart[+e.target.dataset.purchaseCost].cost=Math.max(0,n(e.target.value)); updatePurchaseUI(); }
    else if(e.target.id==='productSearch'||e.target.id==='productStockFilter') filterProducts();
    else if(['salesSearch','salesFrom','salesTo'].includes(e.target.id)) filterSales();
    else if(e.target.id==='customerSearch') filterCustomers();
    else if(e.target.id==='supplierSearch') filterSuppliers();
    else if(['reportFrom','reportTo'].includes(e.target.id)) refreshReport();
  });
  document.addEventListener('keydown',e=>{
    if(e.key==='Enter'&&e.target.id==='modalPriceSearch'){ e.preventDefault(); qs('#modalLookupResult').innerHTML=lookupHTML(e.target.value); }
    if(e.key==='Enter'&&e.target.id==='dashPriceSearch'){ e.preventDefault(); qs('#dashLookupResult').innerHTML=lookupHTML(e.target.value); }
    if(e.key==='Enter'&&e.target.id==='unlockPin'){ e.preventDefault(); unlockApp(); }
  });
  document.addEventListener('submit',e=>{
    e.preventDefault();
    if(e.target.id==='settingsForm') saveSettingsForm();
    if(e.target.id==='pinForm') savePinForm();
  });
  qs('#menuBtn').addEventListener('click',()=>qs('.sidebar').classList.toggle('open'));
}

async function init(){
  bindGlobalEvents(); state=await loadState(); updateBrand(); renderNav(); renderPage();
  if('serviceWorker' in navigator && location.protocol==='https:') navigator.serviceWorker.register('./sw.js').catch(()=>{});
  if(state.settings.pinEnabled&&state.settings.adminPin)showLockScreen();else{qs('#startup').classList.add('hidden');qs('#appShell').classList.remove('hidden');}
}

init().catch(err=>{console.error(err);qs('#startupText').textContent='Could not start the store manager. Please refresh the page.';});